<?php
require_once __DIR__.'/../../config/bootstrap.php'; require_internal();
$allowed=['vendas','venda_itens','encomendas','produtos','movimentacoes_estoque','compras','fornecedores','movimentacoes_caixa','caixas','movimentacoes_financeiras','parcelas','usuarios','clientes','logs'];$table=$_GET['table']??'';if(!in_array($table,$allowed,true)){http_response_code(400);exit('Tabela inválida.');}$rows=db()->query('SELECT * FROM '.$table)->fetchAll();header('Content-Type: text/csv; charset=UTF-8');header('Content-Disposition: attachment; filename="'.preg_replace('/[^a-z0-9_-]/i','_',$table).'.csv"');echo "\xEF\xBB\xBF";$out=fopen('php://output','w');if($rows)fputcsv($out,array_keys($rows[0]),';');foreach($rows as $r)fputcsv($out,array_values($r),';');fclose($out);log_action('exportação CSV',$table);exit;
